// Customer storefront (mobile-first glass UI)
const C = {};
function shell(inner, active = '') {
  const u = S.user;
  $('#app').innerHTML = `<header class="top"><div class="bar glass">
    <a class="logo" href="#/"><img src="/img/logo.svg" alt=""><span>Mohan Mishra</span></a>
    <form class="search" id="sf"><input id="sq" placeholder="Search CNC, gensets, compressors, brands…" value="${esc(C.lastQ || '')}" autocomplete="off" list="sugg"><datalist id="sugg"></datalist><button class="btn sm">Search</button></form>
    <nav class="nav"><a class="pill hide-m ${active === 'rent' ? 'on' : ''}" href="#/search?mode=rental">Rent</a>
    <a class="pill hide-m" href="#/cart">🛒 <b id="cc">${S.cartCount || 0}</b></a>
    ${u ? `<a class="pill hide-m" href="#/notifications">🔔</a><a class="pill" href="#/account">${esc((u.name || 'Me').split(' ')[0])}</a>` : `<a class="pill on" href="#/login">Login</a>`}</nav></div></header>
    <main class="wrap" id="main">${inner}</main>
    <div class="cartpill" id="cartpill" onclick="go('#/cart')"><span>🛒 <b id="cpc">${S.cartCount}</b> item(s) · <b id="cpt">${inr(C.cartTotal || 0)}</b></span><button class="btn sm">View cart ›</button></div>
    <nav class="bottomnav glass">${[['#/', '🏠', 'Home'], ['#/categories', '🧭', 'Categories'], ['#/search?mode=rental', '🚜', 'Rent'], ['#/orders', '📦', 'Orders'], ['#/account', '👤', 'Account']].map(([h, i, l]) => `<a href="${h}" class="${active === l ? 'on' : ''}"><span style="font-size:20px">${i}</span>${l}</a>`).join('')}</nav>
    <footer class="wrap muted small" style="padding-bottom:120px"><div class="card row between"><span>© Mohan Mishra Industrial Marketplace · GST-compliant B2B/B2C machinery</span><span class="row"><a href="#/page/about">About</a><a href="#/page/terms">Terms</a><a href="#/page/privacy">Privacy</a><a href="#/page/refund">Refunds</a><a href="#/faqs">FAQs</a><a href="#/support">Support</a><a href="/vendor">Sell on Mohan Mishra</a></span></div></footer>`;
  $('#sf').onsubmit = e => { e.preventDefault(); C.lastQ = $('#sq').value.trim(); go('#/search?q=' + encodeURIComponent(C.lastQ)); };
  let t; $('#sq').oninput = () => { clearTimeout(t); t = setTimeout(async () => { const q = $('#sq').value.trim(); if (q.length < 2) return; const d = await GET('/search/suggest?q=' + encodeURIComponent(q), { quiet: 1 }).catch(() => null); if (d) $('#sugg').innerHTML = [...(d.products || []), ...(d.categories || []), ...(d.brands || [])].map(x => `<option value="${esc(x.name)}">`).join(''); }, 200); };
  updateCartPill();
}
function updateCartPill() { const p = $('#cartpill'); if (p) p.style.visibility = S.cartCount > 0 ? 'visible' : 'hidden'; if ($('#cc')) $('#cc').textContent = S.cartCount; if ($('#cpc')) { $('#cpc').textContent = S.cartCount; $('#cpt').textContent = inr(C.cartTotal); } }
async function refreshCart() { if (!S.token || S.user?.role !== 'customer') { S.cartCount = 0; return; } const c = await GET('/cart', { quiet: 1 }).catch(() => null); S.cartCount = c?.item_count || 0; C.cartTotal = c?.grand_total || 0; updateCartPill(); return c; }
const needLogin = () => { if (!S.token) { toast('Please log in to continue'); go('#/login?next=' + encodeURIComponent(location.hash)); return true; } return false; };
function card(p) {
  const im = p.image || imgsOf(p)[0]; const rp = p.rental_available ? (p.rent_daily ? inr(p.rent_daily) + '/day' : p.rent_monthly ? inr(p.rent_monthly) + '/mo' : '') : '';
  return `<div class="glass prod" onclick="go('#/p/${p.id}')"><div class="img">${img(im, p.name)}</div>
  <div class="row" style="gap:4px">${p.condition && p.condition !== 'new' ? tag(p.condition) : ''}${p.rental_available ? '<span class="tag peach">Rent</span>' : ''}${p.featured ? '<span class="tag">Featured</span>' : ''}</div>
  <div class="name">${esc(p.name)}</div>${stars(p.rating, p.rating_count)}
  <div class="muted small">${esc(p.vendor_name || '')}${p.location_city ? ' · ' + esc(p.location_city) : ''}</div>
  <div class="row between"><div>${p.purchase_available ? `<span class="price">${inr(p.price)}</span>${p.mrp > p.price ? `<span class="mrp">${inr(p.mrp)}</span>` : ''}` : `<span class="price">${rp}</span>`}${p.purchase_available && rp ? `<div class="small muted">or ${rp}</div>` : ''}</div>
  ${p.purchase_available ? `<button class="plus" title="Add to cart" onclick="event.stopPropagation();C.add(${p.id})">+</button>` : ''}</div></div>`;
}
C.add = async (id, qty = 1) => { if (needLogin()) return; await POST('/cart/items', { product_id: id, qty }); toast('Added to cart'); await refreshCart(); };
const grid = items => items?.length ? `<div class="grid">${items.map(card).join('')}</div>` : '<div class="empty card">No machines found.</div>';

on('customer', '/', async () => {
  shell('<div class="card">Loading…</div>', 'Home'); const h = await GET('/home');
  const sec = (t, items, link) => items?.length ? `<div class="sec"><h2>${t}</h2>${link ? `<a class="pill" href="${link}">See all ›</a>` : ''}</div>${grid(items.slice(0, 8))}` : '';
  $('#main').innerHTML = `${h.announcements?.length ? `<div class="glass" style="padding:10px 16px;border-radius:999px;margin-bottom:12px">📢 <b>${esc(h.announcements[0].title)}</b> <span class="muted">${esc(h.announcements[0].body)}</span></div>` : ''}
   <div class="banner">${h.banners.map(b => `<div class="glass" onclick="location.href='${esc(b.link || '#/')}'">${img(b.image)}<div class="cap glass"><h2 style="margin:0">${esc(b.title)}</h2><div class="muted">${esc(b.subtitle || '')}</div></div></div>`).join('')}</div>
   <div class="sec"><h2>Categories</h2><a class="pill" href="#/categories">All ›</a></div>
   <div class="chips">${h.categories.map(c => `<div class="glass cat" onclick="go('#/search?category_id=${c.id}')">${img(c.image || c.icon, c.name)}${esc(c.name)}</div>`).join('')}</div>
   ${sec('Featured machines', h.featured, '#/search?featured=1')}${sec('Available for rent', h.rental, '#/search?mode=rental')}${sec('Popular right now', h.popular, '#/search?sort=popular')}${sec('Recommended for you', h.recommended)}${sec('Recently viewed', h.recently_viewed)}${sec('New arrivals', h.recent, '#/search?sort=newest')}
   ${h.featured_vendors?.length ? `<div class="sec"><h2>Verified sellers</h2></div><div class="chips">${h.featured_vendors.map(v => `<a class="glass cat" style="min-width:170px" href="#/vendor-store/${v.id}">${img(v.logo || '/img/logo.svg')}<b>${esc(v.business_name)}</b><span class="muted">${esc(v.city)}</span>${stars(v.rating, v.rating_count)}</a>`).join('')}</div>` : ''}
   <div class="card mt row between"><div><h3>Need a custom machine or bulk quote?</h3><div class="muted">Send one requirement, get quotations from multiple verified vendors.</div></div><a class="btn green" href="#/enquire">Request quotation</a></div>`;
});
on('customer', '/categories', async () => { shell('', 'Categories'); const cats = await GET('/categories'); const list = cats.items || cats;
  $('#main').innerHTML = `<h1>Categories</h1><div class="grid">${list.filter(c => !c.parent_id).map(c => `<div class="glass card"><div class="row">${img(c.image || c.icon)}<h3><a href="#/search?category_id=${c.id}">${esc(c.name)}</a></h3></div><div class="row mt">${(c.children || list.filter(x => x.parent_id === c.id)).map(s => `<a class="pill" href="#/search?category_id=${s.id}">${esc(s.name)}</a>`).join('')}</div></div>`).join('')}</div>`; });
on('customer', '/search', async q => {
  shell('', q.mode === 'rental' ? 'Rent' : ''); const page = q.page || 1;
  const qs = new URLSearchParams({ ...q, page, limit: 24 }).toString(); const d = await GET('/products?' + qs);
  const f = d.facets || {}; const sel = (k, opts, label) => `<label>${label}</label><select data-k="${k}"><option value="">Any</option>${opts.map(o => `<option value="${esc(o.id ?? o.value ?? o)}" ${String(q[k]) === String(o.id ?? o.value ?? o) ? 'selected' : ''}>${esc(o.name ?? o.label ?? o)}${o.count !== undefined ? ` (${o.count})` : ''}</option>`).join('')}</select>`;
  $('#main').innerHTML = `<div class="side"><aside class="card" id="filters"><h3>Filters</h3>
    ${sel('mode', [{ id: 'purchase', name: 'Buy' }, { id: 'rental', name: 'Rent' }], 'Buy or rent')}
    ${sel('category_id', f.categories || [], 'Category')}${sel('brand_id', f.brands || [], 'Brand')}
    ${sel('condition', ['new', 'used', 'refurbished'], 'Condition')}${sel('fuel_type', f.fuel_types || ['Diesel', 'Electric', 'Petrol'], 'Fuel / power')}
    ${sel('state', f.states || [], 'Location (state)')}<label>City</label><input data-k="city" value="${esc(q.city || '')}">
    <div class="two" style="gap:8px"><div><label>Min ₹</label><input data-k="min_price" type="number" value="${esc(q.min_price || '')}"></div><div><label>Max ₹</label><input data-k="max_price" type="number" value="${esc(q.max_price || '')}"></div></div>
    ${sel('min_rating', [{ id: 4, name: '4★ & up' }, { id: 3, name: '3★ & up' }], 'Rating')}<label><input type="checkbox" data-k="in_stock" style="width:auto" ${q.in_stock ? 'checked' : ''}> In stock only</label>
    <label>Near me (km)</label><div class="row"><input data-k="radius_km" type="number" placeholder="e.g. 100" value="${esc(q.radius_km || '')}" style="flex:1"><button class="btn ghost sm" id="geo">📍</button></div>
    <div class="row mt"><button class="btn block" id="apply">Apply</button><a class="btn ghost block" href="#/search">Reset</a></div></aside>
    <section><div class="row between"><h2>${q.q ? `Results for “${esc(q.q)}”` : q.mode === 'rental' ? 'Machines for rent' : 'All machinery'} <span class="muted small">${d.total} found</span></h2>
    <select id="sort" style="width:auto">${[['relevance', 'Relevance'], ['price_asc', 'Price: low to high'], ['price_desc', 'Price: high to low'], ['rating', 'Top rated'], ['newest', 'Newest'], ['popular', 'Popularity'], ['distance', 'Nearest']].map(([v, l]) => `<option value="${v}" ${q.sort === v ? 'selected' : ''}>${l}</option>`).join('')}</select></div>
    ${grid(d.items)}${pager(d, p => go('#/search?' + new URLSearchParams({ ...q, page: p })))}</section></div>`;
  const apply = extra => { const o = { ...(q.q ? { q: q.q } : {}), ...extra }; $$('#filters [data-k]').forEach(i => { const v = i.type === 'checkbox' ? (i.checked ? 1 : '') : i.value; if (v !== '') o[i.dataset.k] = v; }); const s = $('#sort').value; if (s !== 'relevance') o.sort = s; if (q.lat) { o.lat = q.lat; o.lng = q.lng; } go('#/search?' + new URLSearchParams(o)); };
  $('#apply').onclick = () => apply(); $('#sort').onchange = () => apply();
  $('#geo').onclick = () => navigator.geolocation ? navigator.geolocation.getCurrentPosition(p => apply({ lat: p.coords.latitude.toFixed(4), lng: p.coords.longitude.toFixed(4), radius_km: $('[data-k=radius_km]').value || 100, sort: 'distance' }), () => toast('Location permission denied', 1)) : toast('Geolocation unavailable', 1);
});
on('customer', '/p/:id', async (q, id) => {
  shell(''); const p = await GET('/products/' + id); const ims = imgsOf(p); const pb = p.price_breakup || {};
  const specs = typeof p.specs === 'string' ? JSON.parse(p.specs || '{}') : (p.specs || {});
  const facts = [['Brand', p.brand_name], ['Model', p.model_no], ['Year', p.mfg_year], ['Condition', p.condition], ['Engine', p.engine_capacity], ['Horsepower', p.horsepower], ['Fuel', p.fuel_type], ['Power', p.power_req], ['Capacity', p.operating_capacity], ['Dimensions', p.dimensions], ['Weight', p.weight], ['Warranty', p.warranty], ['HSN', p.hsn], ['GST', p.gst_rate + '%'], ...Object.entries(specs)].filter(x => x[1]);
  $('#main').innerHTML = `<div class="two"><div class="gallery"><div class="main glass">${img(ims[0], p.name)}</div><div class="thumbs">${ims.map((s, i) => `<img src="${esc(s)}" class="${i ? '' : 'on'}" data-i="${i}">`).join('')}</div>
    ${(typeof p.videos === 'string' ? JSON.parse(p.videos || '[]') : p.videos || []).map(v => `<a class="pill" href="${esc(v)}" target="_blank" rel="noopener">▶ Product video</a>`).join('')}</div>
   <div class="stack"><div class="card"><div class="row">${tag(p.condition)}${p.in_stock ? '<span class="tag green">In stock</span>' : '<span class="tag red">Out of stock</span>'}${p.rental_available ? '<span class="tag peach">Available for rent</span>' : ''}</div>
     <h1>${esc(p.name)}</h1>${stars(p.rating, p.rating_count)}
     <div class="muted small mt">Sold by <a href="#/vendor-store/${p.vendor_id}"><b>${esc(p.vendor_name)}</b></a> · ${esc(p.vendor_city || '')} ${stars(p.vendor_rating)}</div>
     ${p.purchase_available ? `<div class="mt"><span class="price" style="font-size:1.6rem">${inr(p.price)}</span>${p.mrp > p.price ? `<span class="mrp">${inr(p.mrp)}</span> <span class="tag green">${Math.round((1 - p.price / p.mrp) * 100)}% off</span>` : ''}<div class="small muted">+ GST ${p.gst_rate}%${p.delivery_charge ? ' · Transport ' + inr(p.delivery_charge) : ''}${p.installation_charge ? ' · Installation ' + inr(p.installation_charge) + ' (optional)' : ''} · MOQ ${p.moq || 1}</div></div>
     ${pb.total ? `<div class="glass mt" style="padding:10px 14px;border-radius:16px"><div class="row between small"><span>Base</span><b>${inr(pb.base ?? pb.price)}</b></div><div class="row between small"><span>GST</span><b>${inr(pb.gst)}</b></div>${pb.transport ? `<div class="row between small"><span>Transport</span><b>${inr(pb.transport)}</b></div>` : ''}<div class="row between"><span>Estimated total</span><b>${inr(pb.total)}</b></div></div>` : ''}
     <div class="row mt"><div class="stepper"><button id="qm">−</button><span id="qv">${p.moq || 1}</span><button id="qp">+</button></div><label style="margin:0"><input type="checkbox" id="inst" style="width:auto"> Installation</label></div>
     <div class="row mt"><button class="btn green" id="addc" ${p.in_stock ? '' : 'disabled'}>Add to cart</button><button class="btn" id="buy" ${p.in_stock ? '' : 'disabled'}>Buy now</button>` : '<div class="row mt">'}
     <button class="btn ghost" id="enq">Request quote</button><button class="pill" id="wish">${p.in_wishlist ? '♥ Saved' : '♡ Save'}</button><button class="pill" id="cmp">⇄ Compare</button><button class="pill" id="share">↗ Share</button></div></div>
     ${p.rental_available ? `<div class="card"><h3>Rent this machine</h3><div class="row">${Object.entries(p.rental_pricing || { hour: p.rent_hourly, day: p.rent_daily, week: p.rent_weekly, month: p.rent_monthly }).filter(x => x[1]).map(([k, v]) => `<span class="pill">${inr(v)}/${k}</span>`).join('')}</div><div class="small muted mt">Security deposit ${inr(p.security_deposit)} (refundable)</div>
      <div class="form"><div><label>Start</label><input type="datetime-local" id="rs"></div><div><label>Unit</label><select id="ru">${['day', 'hour', 'week', 'month'].filter(u => (p.rental_pricing || {})[u] ?? p['rent_' + (u === 'day' ? 'daily' : u + 'ly')]).map(u => `<option>${u}</option>`).join('')}</select></div><div><label>Duration</label><input type="number" id="rd" value="3" min="1"></div></div>
      <div id="rq" class="small mt"></div><div class="row mt"><button class="btn ghost" id="rquote">Check price & availability</button><button class="btn green" id="rbook">Request rental</button></div></div>` : ''}
     <div class="card"><h3>Specifications</h3>${table(facts.map(([k, v]) => ({ k, v })), [{ k: 'k', l: 'Spec' }, { k: 'v', l: 'Value' }])}</div></div></div>
   <div class="two mt"><div class="card"><h3>Description</h3><p style="white-space:pre-wrap">${esc(p.description || '')}</p>${p.maintenance ? `<h3>Maintenance</h3><p>${esc(p.maintenance)}</p>` : ''}<h3>Return & cancellation</h3><p class="small muted">${esc(p.return_policy || 'As per marketplace refund policy.')} ${esc(p.cancellation_policy || '')}</p></div>
   <div class="card"><h3>Reviews</h3>${(p.reviews || []).map(r => `<div class="glass" style="padding:10px 14px;border-radius:16px;margin-bottom:8px">${stars(r.rating)} <b>${esc(r.title || '')}</b><div class="small">${esc(r.comment || '')}</div><div class="small muted">${esc(r.user_name || r.name || '')} · ${dd(r.created_at)}${r.verified ? ' · ✔ Verified purchase' : ''}</div>${r.vendor_reply ? `<div class="small"><b>Seller:</b> ${esc(r.vendor_reply)}</div>` : ''}</div>`).join('') || '<div class="muted">No reviews yet.</div>'}
    <button class="pill mt" id="report">⚑ Report listing</button></div></div>
   ${p.similar?.length ? `<div class="sec"><h2>Similar machines</h2></div>${grid(p.similar)}` : ''}`;
  $$('.thumbs img').forEach(t => t.onclick = () => { $('.gallery .main img').src = t.src; $$('.thumbs img').forEach(x => x.classList.toggle('on', x === t)); });
  let qty = p.moq || 1; const qv = $('#qv');
  if (qv) { $('#qm').onclick = () => { qty = Math.max(p.moq || 1, qty - 1); qv.textContent = qty; }; $('#qp').onclick = () => { qty = Math.min(p.stock || 99, qty + 1); qv.textContent = qty; };
    $('#addc').onclick = async () => { if (needLogin()) return; await POST('/cart/items', { product_id: p.id, qty, with_installation: $('#inst').checked }); toast('Added to cart'); refreshCart(); };
    $('#buy').onclick = async () => { if (needLogin()) return; await POST('/cart/items', { product_id: p.id, qty, with_installation: $('#inst').checked }); await refreshCart(); go('#/checkout'); }; }
  $('#enq').onclick = () => go('#/enquire?product_id=' + p.id);
  $('#wish').onclick = async () => { if (needLogin()) return; if (p.in_wishlist) await DEL('/wishlist/' + p.id); else await POST('/wishlist', { product_id: p.id }); p.in_wishlist = !p.in_wishlist; $('#wish').textContent = p.in_wishlist ? '♥ Saved' : '♡ Save'; };
  $('#cmp').onclick = async () => { if (needLogin()) return; await POST('/compare', { product_id: p.id }); toast('Added to compare'); go('#/compare'); };
  $('#share').onclick = () => { const url = location.origin + '/#/p/' + p.id; if (navigator.share) navigator.share({ title: p.name, url }); else { navigator.clipboard?.writeText(url); toast('Link copied'); } };
  $('#report').onclick = async () => { if (needLogin()) return; const r = await ask('Report this listing', [{ k: 'reason', l: 'Reason', t: 'select', o: ['fake', 'wrong_info', 'prohibited', 'pricing', 'other'] }, { k: 'details', l: 'Details', t: 'textarea' }]); if (r) { await POST('/reports', { target_type: 'product', target_id: p.id, ...r }); toast('Thanks, our team will review it'); } };
  if ($('#rs')) { const d0 = new Date(Date.now() + 864e5); d0.setMinutes(0); $('#rs').value = new Date(d0 - d0.getTimezoneOffset() * 6e4).toISOString().slice(0, 16);
    const body = () => ({ product_id: p.id, unit: $('#ru').value, duration: +$('#rd').value, start_at: new Date($('#rs').value).toISOString() });
    $('#rquote').onclick = async () => { if (needLogin()) return; const r = await POST('/rentals/quote', body()); $('#rq').innerHTML = `Rent ${inr(r.rent_amount)} + GST ${inr((r.cgst || 0) + (r.sgst || 0) + (r.igst || 0))} + transport ${inr(r.transport)} + deposit ${inr(r.deposit)} = <b>${inr(r.total)}</b> · Advance ${inr(r.advance_amount ?? r.advance)} · ${r.availability?.available > 0 ? '<span class="tag green">Available</span>' : '<span class="tag red">Not available</span>'}`; };
    $('#rbook').onclick = async () => { if (needLogin()) return; const r = await POST('/rentals', body()); toast('Rental request sent to vendor'); go('#/rentals/' + r.id); }; }
});
on('customer', '/vendor-store/:id', async (q, id) => { shell(''); const v = await GET('/vendors/' + id); const pr = await GET('/products?vendor_id=' + id + '&limit=48');
  $('#main').innerHTML = `<div class="card row">${img(v.logo || '/img/logo.svg')}<div><h1>${esc(v.business_name)}</h1><div class="muted">${esc(v.city || '')}, ${esc(v.state || '')} · ${stars(v.rating, v.rating_count)} ${v.kyc_status === 'approved' ? '<span class="tag green">✔ Verified</span>' : ''}</div><p>${esc(v.description || '')}</p></div></div><div class="sec"><h2>Machines</h2></div>${grid(pr.items)}`; });
on('customer', '/compare', async () => { if (needLogin()) return; shell(''); const d = await GET('/compare'); const items = d.items || d;
  const keys = ['price', 'condition', 'brand_name', 'model_no', 'horsepower', 'engine_capacity', 'fuel_type', 'operating_capacity', 'weight', 'warranty', 'rating', 'vendor_name'];
  $('#main').innerHTML = `<h1>Compare</h1><div class="card tablewrap">${items.length ? `<table><tr><th></th>${items.map(p => `<th>${esc(p.name)}<br><button class="btn ghost sm" onclick="DEL('/compare/${p.id}').then(route)">Remove</button></th>`).join('')}</tr>${keys.map(k => `<tr><td><b>${k.replace(/_/g, ' ')}</b></td>${items.map(p => `<td>${k === 'price' ? inr(p[k]) : esc(p[k] ?? '—')}</td>`).join('')}</tr>`).join('')}</table>` : '<div class="empty">Add machines to compare from product pages.</div>'}</div>`; });
// ---- auth ----
on('customer', '/login', q => { shell(''); const next = q.next || '#/';
  $('#main').innerHTML = `<div class="card" style="max-width:440px;margin:30px auto"><h1>Welcome 👋</h1><p class="muted">Login or create an account with your mobile number or email.</p>
   <div class="tabs"><button class="pill on" data-t="otp">OTP</button><button class="pill" data-t="pw">Password</button><button class="pill" data-t="reg">Register</button></div>
   <div id="t-otp"><label>Mobile or email</label><input id="ot" placeholder="98765 43210"><div id="otp2" class="hide"><label>OTP</label><input id="oc" inputmode="numeric" maxlength="6"><div class="form"><div><label>Name (new users)</label><input id="on"></div><div><label>Account type</label><select id="oa"><option value="individual">Individual</option><option value="business">Business</option></select></div></div></div>
     <button class="btn block mt" id="ob">Send OTP</button></div>
   <div id="t-pw" class="hide"><label>Mobile or email</label><input id="pi"><label>Password</label><input id="pp" type="password"><button class="btn block mt" id="pb">Login</button><a href="#/forgot" class="small">Forgot password?</a></div>
   <div id="t-reg" class="hide">${formHtml([{ k: 'name', l: 'Full name' }, { k: 'mobile', l: 'Mobile' }, { k: 'email', l: 'Email (optional)' }, { k: 'password', l: 'Password (min 8)', t: 'password' }, { k: 'account_type', l: 'Account type', t: 'select', o: [['individual', 'Individual'], ['business', 'Business']] }, { k: 'business_name', l: 'Business name' }, { k: 'gstin', l: 'GSTIN (optional)' }])}<button class="btn ghost mt" id="rsend">Send OTP to mobile</button><label>OTP</label><input id="rotp"><button class="btn block mt" id="rb">Create account</button></div>
   <div class="row mt" style="justify-content:center"><button class="btn ghost block" id="gg">Continue with Google</button></div>
   <p class="small muted mt">Demo: rahul@example.com / Customer@123 · OTP codes are shown in dev mode.</p></div>`;
  $$('[data-t]').forEach(b => b.onclick = () => { $$('[data-t]').forEach(x => x.classList.toggle('on', x === b)); ['otp', 'pw', 'reg'].forEach(t => $('#t-' + t).classList.toggle('hide', t !== b.dataset.t)); });
  const done = async d => { setAuth(d); await refreshCart(); toast('Welcome ' + (d.user.name || '')); if (d.user.role === 'vendor') location.href = '/vendor'; else if (['admin', 'staff'].includes(d.user.role)) location.href = '/admin'; else go(next); };
  let sent = false; $('#ob').onclick = async () => { const t = $('#ot').value.trim(); if (!sent) { const r = await POST('/auth/otp/send', { target: t, purpose: 'login' }); sent = true; $('#otp2').classList.remove('hide'); $('#ob').textContent = 'Verify & continue'; toast(r.dev_code ? 'Dev OTP: ' + r.dev_code : 'OTP sent'); if (r.dev_code) $('#oc').value = r.dev_code; } else done(await POST('/auth/otp/verify', { target: t, code: $('#oc').value.trim(), name: $('#on').value || undefined, account_type: $('#oa').value })); };
  $('#pb').onclick = async () => done(await POST('/auth/login', { identifier: $('#pi').value.trim(), password: $('#pp').value }));
  $('#rsend').onclick = async () => { const r = await POST('/auth/otp/send', { target: readForm($('#t-reg')).mobile, purpose: 'register' }); toast(r.dev_code ? 'Dev OTP: ' + r.dev_code : 'OTP sent'); if (r.dev_code) $('#rotp').value = r.dev_code; };
  $('#rb').onclick = async () => done(await POST('/auth/register', { ...readForm($('#t-reg')), otp: $('#rotp').value.trim() }));
  $('#gg').onclick = async () => { const r = await ask('Google sign-in (mock provider)', [{ k: 'email', l: 'Google email', v: 'demo.google@example.com' }, { k: 'name', l: 'Name', v: 'Google User' }], 'Continue'); if (r) done(await POST('/auth/google', { id_token: `mock:${r.email}:${r.name}` })); };
});
on('customer', '/forgot', () => { shell(''); $('#main').innerHTML = `<div class="card" style="max-width:440px;margin:30px auto"><h2>Reset password</h2><label>Mobile or email</label><input id="ft"><button class="btn ghost mt" id="fs">Send OTP</button><label>OTP</label><input id="fc"><label>New password</label><input id="fp" type="password"><button class="btn block mt" id="fb">Reset</button></div>`;
  $('#fs').onclick = async () => { const r = await POST('/auth/forgot-password', { identifier: $('#ft').value.trim() }); toast(r.dev_code ? 'Dev OTP: ' + r.dev_code : 'OTP sent'); if (r.dev_code) $('#fc').value = r.dev_code; };
  $('#fb').onclick = async () => { await POST('/auth/reset-password', { identifier: $('#ft').value.trim(), code: $('#fc').value.trim(), new_password: $('#fp').value, password: $('#fp').value }); toast('Password updated, please log in'); go('#/login'); }; });
// ---- cart & checkout ----
on('customer', '/cart', async () => { if (needLogin()) return; shell(''); const c = await refreshCart();
  if (!c?.groups?.length) { $('#main').innerHTML = '<div class="card empty"><h2>Your cart is empty</h2><a class="btn green" href="#/">Browse machinery</a></div>'; return; }
  $('#main').innerHTML = `<h1>Cart</h1><div class="side" style="grid-template-columns:1fr 340px"><div class="stack">${c.groups.map(g => `<div class="card"><h3>📦 ${esc(g.vendor_name)} <span class="muted small">${esc(g.vendor_city || '')}</span></h3>${g.lines.map(l => `<div class="row between" style="padding:8px 0;border-bottom:1px solid #fff8"><div class="row" style="flex:1;min-width:200px"><div style="width:72px;height:54px;border-radius:12px;overflow:hidden">${img(l.image)}</div><div><a href="#/p/${l.product_id}"><b>${esc(l.name)}</b></a><div class="small muted">${inr(l.unit_price)} · GST ${l.gst_rate}%${l.transport ? ' · transport ' + inr(l.transport) : ''}${l.installation ? ' · install ' + inr(l.installation) : ''}</div></div></div>
     <div class="row"><div class="stepper"><button onclick="C.qty(${l.product_id},${l.qty - 1})">−</button><span>${l.qty}</span><button onclick="C.qty(${l.product_id},${l.qty + 1})">+</button></div><b style="min-width:100px;text-align:right">${inr(l.total)}</b><button class="pill" onclick="C.qty(${l.product_id},0)">✕</button></div></div>`).join('')}<div class="right small muted mt">Seller subtotal ${inr(g.total)}</div></div>`).join('')}
     ${c.issues?.length ? `<div class="card"><b>Needs attention:</b> ${c.issues.map(i => esc(i.message || i)).join('; ')}</div>` : ''}</div>
    <div class="card" style="position:sticky;top:90px">${summary(c)}<div class="row mt"><input id="cpn" placeholder="Coupon code" value="${esc(C.coupon || '')}" style="flex:1"><button class="btn ghost sm" id="cpa">Apply</button></div><div class="small muted">Try WELCOME5 · FLAT2000 · TOOLS10</div><a class="btn green block mt" href="#/checkout">Checkout ›</a></div></div>`;
  $('#cpa').onclick = async () => { C.coupon = $('#cpn').value.trim(); await POST('/cart/apply-coupon', { code: C.coupon }); toast('Coupon applied'); route(); }; });
C.qty = async (pid, q) => { if (q <= 0) await DEL('/cart/items/' + pid); else await PATCH('/cart/items/' + pid, { qty: q }); route(); };
function summary(c) { const r = (l, v, b) => v ? `<div class="row between ${b ? '' : 'small'}"><span>${l}</span>${b ? `<b>${inr(v)}</b>` : `<span>${inr(v)}</span>`}</div>` : '';
  return `<h3>Price details</h3>${r('Items', c.subtotal)}${r('Discount', -(c.discount || 0) - (c.coupon_discount || 0))}${r('Transport', c.transport)}${r('Installation', c.installation)}${r('Taxable value', c.taxable)}${r('CGST', c.cgst)}${r('SGST', c.sgst)}${r('IGST', c.igst)}${r('Platform fee (incl. GST)', (c.platform_fee || 0) + (c.platform_fee_gst || 0))}<hr style="border:0;border-top:1px solid #fff">${r('Total payable', c.grand_total, 1)}`; }
on('customer', '/checkout', async () => { if (needLogin()) return; shell(''); const [c, me] = await Promise.all([refreshCart(), GET('/auth/me')]); const addrs = me.addresses || (await GET('/auth/me/addresses')).items || [];
  if (!c?.groups?.length) return go('#/cart'); const cfg = S.config || {};
  $('#main').innerHTML = `<h1>Checkout</h1><div class="side" style="grid-template-columns:1fr 340px"><div class="stack"><div class="card"><div class="row between"><h3>Delivery & billing address</h3><button class="btn ghost sm" id="na">+ New address</button></div>
     ${addrs.length ? `<label>Ship to</label><select id="ship">${addrs.map(a => `<option value="${a.id}" ${a.is_default ? 'selected' : ''}>${esc(a.label || '')} — ${esc(a.name)}, ${esc(a.line1)}, ${esc(a.city)}, ${esc(a.state)} ${esc(a.pincode)}</option>`).join('')}</select><label>Bill to</label><select id="bill">${addrs.map(a => `<option value="${a.id}" ${a.is_default ? 'selected' : ''}>${esc(a.label || '')} — ${esc(a.name)}, ${esc(a.city)}${a.gstin ? ' · GSTIN ' + esc(a.gstin) : ''}</option>`).join('')}</select>` : '<p class="muted">Add an address to continue.</p>'}
     <label>GSTIN for invoice (business purchase, optional)</label><input id="gst" value="${esc(me.user?.gstin || me.gstin || '')}"></div>
    <div class="card"><h3>Payment plan</h3><div class="row">${[['full', 'Pay in full'], ['advance', `Advance ${cfg.advance_pct || 25}% now`], ['partial', 'Partial payments']].map(([v, l], i) => `<label class="pill" style="margin:0"><input type="radio" name="plan" value="${v}" ${i ? '' : 'checked'} style="width:auto"> ${l}</label>`).join('')}</div>
     <h3 class="mt">Payment method</h3><div class="row">${(cfg.payment_methods || ['upi', 'card', 'netbanking']).map((m, i) => `<label class="pill" style="margin:0"><input type="radio" name="pm" value="${m}" ${i ? '' : 'checked'} style="width:auto"> ${m.toUpperCase()}</label>`).join('')}</div><p class="small muted">Payments run through the configured gateway (mock in this environment).</p>
     <label>Order notes</label><textarea id="notes" rows="2"></textarea></div></div>
   <div class="card" style="position:sticky;top:90px">${summary(c)}<button class="btn green block mt" id="place" ${addrs.length ? '' : 'disabled'}>Place order & pay</button></div></div>`;
  $('#na').onclick = async () => { if (await addressForm()) route(); };
  $('#place').onclick = async () => { const plan = $('[name=plan]:checked').value; const o = await POST('/checkout', { shipping_address_id: +$('#ship').value, billing_address_id: +$('#bill').value, gstin: $('#gst').value.trim() || undefined, coupon_code: C.coupon || undefined, payment_plan: plan, payment_method: $('[name=pm]:checked').value, notes: $('#notes').value || undefined });
    C.coupon = null; await refreshCart(); toast('Order ' + o.order_no + ' placed'); await pay({ order_id: o.id, purpose: plan === 'advance' ? 'advance' : 'full', method: $('[name=pm]:checked')?.value }); go('#/orders/' + o.id); }; });
async function addressForm(a = {}) { const r = await ask(a.id ? 'Edit address' : 'New address', [{ k: 'label', l: 'Label', v: a.label || 'Site' }, { k: 'name', l: 'Contact name', v: a.name || S.user?.name }, { k: 'mobile', l: 'Mobile', v: a.mobile || S.user?.mobile }, { k: 'line1', l: 'Address line 1', v: a.line1, full: 1 }, { k: 'line2', l: 'Line 2', v: a.line2 }, { k: 'city', l: 'City', v: a.city }, { k: 'state', l: 'State', v: a.state }, { k: 'pincode', l: 'Pincode', v: a.pincode }, { k: 'gstin', l: 'GSTIN (optional)', v: a.gstin }, { k: 'is_default', l: 'Default', t: 'checkbox', v: a.is_default }], 'Save');
  if (!r) return null; return a.id ? api('PUT', '/auth/me/addresses/' + a.id, r) : POST('/auth/me/addresses', r); }
// Mock gateway sheet (real Razorpay/Cashfree checkout would open here when keys are configured)
async function pay(body) { const init = await POST('/payments/init', { provider: 'mock', ...body });
  return new Promise(res => modal(`<h3>Secure payment</h3><p>Amount <b style="font-size:1.4rem">${inr(init.payment.amount)}</b></p><p class="small muted">Ref ${esc(init.payment.ref)} · ${esc(init.payment.gateway_order_id)} · Mock gateway (no money moves)</p>
   <div class="row"><button class="btn green" data-ok>Pay successfully</button><button class="btn red" data-f>Simulate failure</button><button class="btn ghost" data-x>Pay later</button></div>`, el => {
    $('[data-ok]', el).onclick = async () => { await POST('/payments/mock/complete', { gateway_order_id: init.payment.gateway_order_id, outcome: 'success' }); closeModal(); toast('Payment successful ✔'); res(true); };
    $('[data-f]', el).onclick = async () => { await POST('/payments/mock/complete', { gateway_order_id: init.payment.gateway_order_id, outcome: 'failure' }, { quiet: 1 }).catch(() => { }); closeModal(); toast('Payment failed — you can retry from the order', 1); res(false); };
    $('[data-x]', el).onclick = () => { closeModal(); res(false); }; })); }
// ---- orders ----
on('customer', '/orders', async q => { if (needLogin()) return; shell('', 'Orders'); const d = await GET('/orders?page=' + (q.page || 1));
  $('#main').innerHTML = `<h1>My orders</h1><div class="tabs"><a class="pill on" href="#/orders">Orders</a><a class="pill" href="#/rentals">Rentals</a><a class="pill" href="#/quotes">Enquiries & quotes</a><a class="pill" href="#/invoices">Invoices</a></div>
   <div class="stack">${d.items.map(o => `<a class="card row between" href="#/orders/${o.id}" style="color:inherit"><div><b>${esc(o.order_no)}</b> ${tag(o.status)} ${tag(o.payment_status)}<div class="small muted">${dt(o.created_at)} · ${o.item_count || ''} item(s) ${o.source === 'quotation' ? '· from quotation' : ''}</div></div><b>${inr(o.grand_total)}</b></a>`).join('') || '<div class="card empty">No orders yet.</div>'}</div>${pager(d, p => go('#/orders?page=' + p))}`; });
on('customer', '/orders/:id', async (q, id) => { if (needLogin()) return; shell('', 'Orders'); const o = await GET('/orders/' + id); const due = Math.round((o.grand_total - o.paid_amount) * 100) / 100;
  $('#main').innerHTML = `<div class="row between"><h1>Order ${esc(o.order_no)}</h1><div class="row">${tag(o.status)} ${tag(o.payment_status)}</div></div>
   <div class="side" style="grid-template-columns:1fr 340px"><div class="stack">${o.sub_orders.map(s => `<div class="card"><div class="row between"><h3>${esc(s.vendor_name)} · ${esc(s.sub_order_no)}</h3>${tag(s.status)}</div>
     ${s.items.map(i => `<div class="row between small" style="padding:6px 0"><span>${esc(i.name)} × ${i.qty}</span><b>${inr(i.total)}</b></div>`).join('')}
     ${s.transporter || s.tracking_no ? `<div class="glass small" style="padding:8px 12px;border-radius:14px">🚚 ${esc(s.transporter || '')} ${s.tracking_no ? '· Tracking ' + esc(s.tracking_no) : ''} ${s.vehicle_no ? '· Vehicle ' + esc(s.vehicle_no) : ''} ${s.expected_delivery ? '· ETA ' + dd(s.expected_delivery) : ''}</div>` : ''}
     <div class="row mt">${['placed', 'accepted', 'packed', 'confirmed'].includes(s.status) ? `<button class="btn ghost sm" onclick="C.req(${o.id},${s.id},'cancel')">Cancel</button>` : ''}${['shipped', 'in_transit', 'out_for_delivery'].includes(s.status) ? `<button class="btn green sm" onclick="POST('/orders/${o.id}/confirm-delivery',{sub_order_id:${s.id}}).then(route)">Confirm delivery</button><button class="btn ghost sm" onclick="C.req(${o.id},${s.id},'delivery_issue')">Delivery issue</button>` : ''}
     ${['delivered', 'completed'].includes(s.status) ? `<button class="btn ghost sm" onclick="C.req(${o.id},${s.id},'return')">Return</button><button class="btn ghost sm" onclick="C.req(${o.id},${s.id},'refund')">Refund</button><button class="btn ghost sm" onclick="C.review(${o.id},${s.items[0]?.product_id},${s.vendor_id})">★ Review</button>` : ''}<button class="btn ghost sm" onclick="C.req(${o.id},${s.id},'dispute')">Dispute</button><button class="btn ghost sm" onclick="C.chat(${s.vendor_id},${o.id})">💬 Chat seller</button></div></div>`).join('')}
    <div class="card"><h3>Tracking timeline</h3><ul class="timeline">${o.events.map(e => `<li><b>${esc(String(e.status).replace(/_/g, ' '))}</b> <span class="small muted">${dt(e.created_at)}</span><div class="small">${esc(e.note || '')}</div></li>`).join('')}</ul></div></div>
   <div class="stack"><div class="card">${summary(o)}<div class="row between small mt"><span>Paid</span><b>${inr(o.paid_amount)}</b></div>${o.refunded_amount ? `<div class="row between small"><span>Refunded</span><b>${inr(o.refunded_amount)}</b></div>` : ''}
     ${due > 0 && o.status !== 'cancelled' ? `<button class="btn green block mt" id="paynow">Pay ${inr(due)}</button>${o.payment_status === 'unpaid' ? `<button class="btn ghost block mt" id="payadv">Pay advance only</button>` : ''}` : ''}
     ${['placed', 'confirmed', 'pending_payment'].includes(o.status) ? `<button class="btn ghost block mt" id="cancel">Cancel order</button>` : ''}<button class="btn ghost block mt" onclick="POST('/orders/${o.id}/reorder').then(()=>{refreshCart();go('#/cart')})">Reorder</button></div>
    <div class="card"><h3>Invoices & receipts</h3>${o.invoices.map(i => `<div class="row between small" style="padding:4px 0"><span>${tag(i.type)} ${esc(i.invoice_no)}</span><button class="pill" onclick="openPdf('/invoices/${i.id}/pdf')">PDF</button></div>`).join('') || '<div class="muted small">Issued after payment.</div>'}</div>
    <div class="card"><h3>Payments</h3>${o.payments.map(p => `<div class="row between small"><span>${esc(p.ref)} ${tag(p.status)}</span><span>${inr(p.amount)} ${p.status === 'failed' ? `<button class="pill" onclick="C.retry(${p.id},${o.id})">Retry</button>` : ''}</span></div>`).join('') || '<div class="muted small">No payments yet</div>'}</div></div></div>`;
  $('#paynow') && ($('#paynow').onclick = async () => { await pay({ order_id: o.id, purpose: 'full' }); route(); });
  $('#payadv') && ($('#payadv').onclick = async () => { await pay({ order_id: o.id, purpose: 'advance' }); route(); });
  $('#cancel') && ($('#cancel').onclick = async () => { const r = await ask('Cancel order', [{ k: 'reason', l: 'Reason', t: 'textarea' }]); if (r) { await POST(`/orders/${o.id}/cancel`, r); toast('Order cancelled'); route(); } }); });
C.retry = async (pid, oid) => { const r = await POST(`/payments/${pid}/retry`, { provider: 'mock' }); modal(`<h3>Retry payment</h3><p>${inr(r.payment.amount)}</p><button class="btn green" data-ok>Pay</button>`, el => $('[data-ok]', el).onclick = async () => { await POST('/payments/mock/complete', { gateway_order_id: r.payment.gateway_order_id }); closeModal(); toast('Paid'); route(); }); };
C.req = async (oid, sid, type) => { const r = await ask({ cancel: 'Cancel item', return: 'Return request', refund: 'Refund request', dispute: 'Raise dispute', delivery_issue: 'Report delivery issue' }[type], [{ k: 'reason', l: 'Reason', t: 'textarea' }, ...(type === 'refund' ? [{ k: 'amount', l: 'Amount (optional)', t: 'number' }] : [])]); if (!r) return; await POST(`/orders/${oid}/requests`, { type, sub_order_id: sid, ...r }); toast('Request submitted'); route(); };
C.review = async (oid, pid, vid) => { const r = await ask('Rate & review', [{ k: 'rating', l: 'Rating', t: 'select', o: [5, 4, 3, 2, 1] }, { k: 'title', l: 'Title' }, { k: 'comment', l: 'Review', t: 'textarea' }]); if (!r) return; await POST('/reviews', { order_id: oid, product_id: pid, vendor_id: vid, ...r, rating: +r.rating }); toast('Thanks for the review!'); };
C.chat = async (vid, oid) => { const c = await POST('/conversations', { vendor_id: vid, order_id: oid, subject: 'Order query' }); go('#/chat/' + (c.id || c.conversation?.id)); };
// ---- enquiries & quotations ----
